{
  "name": "@npv12/opencode-ghost",
  "version": "2.0.0",
  "description": "Ghost text prompt completion for the OpenCode V2 terminal",
  "author": "pank-su",
  "contributors": [
    {
      "name": "npv12",
      "url": "https://github.com/npv12"
    }
  ],
  "license": "MIT",
  "type": "module",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/npv12/opencode-ghost.git"
  },
  "bugs": {
    "url": "https://github.com/npv12/opencode-ghost/issues"
  },
  "homepage": "https://github.com/npv12/opencode-ghost#readme",
  "keywords": [
    "opencode",
    "plugin",
    "tui",
    "autocomplete",
    "completion",
    "ghost",
    "prompt"
  ],
  "packageManager": "bun@1.3.14",
  "engines": {
    "node": ">=26.4.0",
    "bun": ">=1.3.14",
    "opencode": ">=2.0.0"
  },
  "publishConfig": {
    "access": "public"
  },
  "scripts": {
    "test:unit": "node --test tests/prediction.test.mjs tests/context.test.mjs tests/editor.test.mjs tests/retry.test.mjs tests/word.test.mjs tests/prompt-budget.test.mjs tests/package.test.mjs tests/options.test.mjs tests/scheduler.test.mjs tests/model-reference.test.mjs tests/diagnostics.test.mjs",
    "test:renderer": "bun test --preload @opentui/solid/preload ./tests/ghost.test.tsx ./tests/ui.test.tsx",
    "test": "bun run test:unit && bun run test:renderer",
    "typecheck": "tsc --noEmit",
    "check": "bun run test && bun run typecheck"
  },
  "files": [
    "tui.ts",
    "src",
    "README.md",
    "LICENSE"
  ],
  "exports": {
    "./tui": "./tui.ts"
  },
  "peerDependencies": {
    "@opentui/core": ">=0.5.17 <0.7",
    "@opentui/solid": ">=0.5.17 <0.7",
    "solid-js": "1.9.12"
  },
  "devDependencies": {
    "@opencode/plugin": "2.2.0",
    "@opencode/theme": "2.1.0",
    "@opentui/core": "0.6.6",
    "@opentui/solid": "0.6.6",
    "@opentui/keymap": "0.6.6",
    "solid-js": "1.9.12",
    "typescript": "5.8.2",
    "@types/bun": "1.4.0"
  }
}
